# Favicons as inline SVG: the Poké Ball for the tracker, crossed swords while in Showdown (used by assemble.py).
import urllib.parse
BALL="<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><circle cx='16' cy='16' r='15' fill='#151515'/><path d='M2.6 14.4A13.5 13.5 0 0 1 29.4 14.4Z' fill='#ef3d4f'/><path d='M2.6 17.6A13.5 13.5 0 0 0 29.4 17.6Z' fill='#f4f4f4'/><circle cx='16' cy='16' r='5.2' fill='#151515'/><circle cx='16' cy='16' r='3.1' fill='#f4f4f4'/></svg>"
SD="<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32' fill='none' stroke-linecap='round'><defs><linearGradient id='g' x1='0' y1='0' x2='0' y2='1'><stop offset='0' stop-color='#e2414f'/><stop offset='1' stop-color='#a8202d'/></linearGradient></defs><circle cx='16' cy='16' r='15.5' fill='url(#g)'/><g transform='translate(6 6)'><g stroke='#fff' stroke-width='2.1'><line x1='3' y1='3' x2='13' y2='13'/><line x1='17' y1='3' x2='7' y2='13'/></g><g stroke='#ffd23f' stroke-width='2'><line x1='11.2' y1='14.8' x2='14.8' y2='11.2'/><line x1='5.2' y1='11.2' x2='8.8' y2='14.8'/></g><g stroke='#4a2a0c' stroke-width='2'><line x1='14.2' y1='14.2' x2='16' y2='16'/><line x1='5.8' y1='14.2' x2='4' y2='16'/></g><g fill='#ffd23f'><circle cx='16.7' cy='16.7' r='1.2'/><circle cx='3.3' cy='16.7' r='1.2'/></g></g></svg>"
uri=lambda s:'data:image/svg+xml,'+urllib.parse.quote(s,safe="/:=' ")
FAV_LINK=f'<link rel="icon" id="favicon" type="image/svg+xml" href="{uri(BALL)}" data-sd="{uri(SD)}">'
